<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Daniel Seuffer</title>
    <link rel="icon" href='data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><defs><linearGradient id="g" x2="0" y2="1"><stop offset="0" stop-color="%23ffc93c"/><stop offset=".6" stop-color="%23ff6b3d"/><stop offset="1" stop-color="%23ff3cac"/></linearGradient></defs><rect width="64" height="64" rx="14" fill="%2307001a"/><circle cx="32" cy="32" r="22" fill="url%28%23g%29"/><path fill="%2307001a" d="M8 34h48v2H8zm0 6h48v3H8zm0 7h48v4H8z"/><path fill="%233ef2ff" d="M6 52h52v2H6z"/></svg>'>
    <meta name="description" content="Hallo, I'm Daniel. I do open source and work for InnoGE.">
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Monoton&family=Kaushan+Script&family=Share+Tech+Mono&display=swap" rel="stylesheet">
    @if (file_exists(public_path('build/manifest.json')) || file_exists(public_path('hot')))
        @vite('resources/js/city.js')
    @endif
    <style>
        :root { --pink: #ff3cac; --blue: #2b86ff; --cyan: #3ef2ff; --sun: #ffc93c; --orange: #ff6b3d; --bg: #07001a; }
        * { box-sizing: border-box; margin: 0; }
        html { background: var(--bg); color: #eae6ff; font: 18px/1.5 'Share Tech Mono', ui-monospace, monospace; }
        body { overflow-x: hidden; }
        a { color: inherit; text-underline-offset: .2em; }
        a:focus-visible { outline: 2px dashed var(--cyan); outline-offset: 6px; }
        ::selection { background: var(--pink); color: var(--bg); }
        html { scrollbar-color: var(--pink) var(--bg); }
        .sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
        .ico { width: .9em; height: .9em; fill: currentColor; vertical-align: -.1em; }

        .drive { position: relative; display: grid; min-height: max(460px, min(66svh, 600px)); overflow: hidden; isolation: isolate;
            background: var(--bg); }
        .drive::after { content: ''; position: absolute; inset: 0; pointer-events: none; background: linear-gradient(transparent 82%, var(--bg)); }
        .city3d { position: absolute; inset: 0; width: 100%; height: 100%; z-index: -1; opacity: 0; transition: opacity 1.2s ease-out; }
        .is-3d .city3d { opacity: 1; }
        .is-3d::after { background: radial-gradient(40% 45% at 50% 52%, rgba(7, 0, 26, .3), transparent), linear-gradient(transparent 90%, var(--bg)); }
        .hero { position: relative; display: grid; place-content: center; justify-items: center; gap: .3rem; padding: 24px 16px 80px; text-align: center; }
        .avatar { width: 168px; height: 168px; object-fit: cover; border-radius: 50%; border: 3px solid #fff; box-shadow: 0 0 0 4px var(--blue), 0 0 30px var(--blue); margin-bottom: .6rem; }
        .hello { font-family: 'Kaushan Script', cursive; font-size: clamp(1.8rem, 6vw, 2.8rem); color: var(--sun); rotate: -5deg; text-shadow: 0 0 10px var(--orange), 0 0 26px var(--pink); }
        .neon { text-wrap: balance; font-family: 'Monoton', cursive; font-weight: normal; font-size: clamp(3rem, 14vw, 7.5rem); line-height: 1; color: #fff; letter-spacing: .02em;
            text-shadow: 0 0 4px #fff, 0 0 12px var(--pink), 0 0 26px var(--pink), 0 0 52px var(--pink), 0 0 90px var(--blue); }

        .sent { margin-top: .6rem; padding: .2rem .9rem; border-radius: 999px; background: var(--bg); color: var(--cyan); letter-spacing: .12em; text-shadow: 0 0 8px var(--cyan); }
        .sent span { color: var(--sun); text-shadow: 0 0 8px var(--orange); }
        main { position: relative; isolation: isolate; overflow: clip; }
        main::before { content: ''; position: absolute; top: 40px; left: -30%; width: 110%; height: 850px; z-index: -1; pointer-events: none;
            background: radial-gradient(ellipse at 30% 45%, rgba(255, 60, 172, .15), transparent 54%), radial-gradient(ellipse at 55% 50%, transparent 30%, rgba(106, 48, 180, .16) 48%, transparent 67%);
            mask-image: radial-gradient(ellipse, #000 30%, transparent 70%); rotate: -18deg; animation: mist-drift 28s ease-in-out infinite alternate; }
        @keyframes mist-drift { from { transform: translate(-12px, 0); } to { transform: translate(24px, 18px); } }
        .side-a { background: radial-gradient(ellipse at 50% 35%, rgba(255, 60, 172, .1), transparent 58%); }
        .side-b { background: radial-gradient(ellipse 50% 38% at 50% 62%, rgba(88, 231, 142, .18), transparent); }
        .bonus { background: radial-gradient(ellipse at 50% 62%, rgba(255, 107, 61, .1), transparent 48%); }
        section, footer { position: relative; padding: 3rem max(16px, calc((100% - 760px) / 2)); }
        section::before, footer::before { content: ''; position: absolute; top: 0; left: 50%; translate: -50% 0; width: min(60%, 420px); height: 1px;
            background: linear-gradient(90deg, transparent, var(--pink), var(--cyan), transparent); box-shadow: 0 0 10px var(--pink); }
        section { display: grid; gap: 1.6rem; justify-items: center; text-align: center; }
        .eyebrow { margin-bottom: -1rem; font-size: .75rem; letter-spacing: .3em; text-transform: uppercase; color: var(--orange); }
        section h2 { text-wrap: balance; font-family: 'Kaushan Script', cursive; font-weight: normal; font-size: clamp(1.8rem, 6vw, 2.4rem); color: var(--cyan); rotate: -3deg; text-shadow: 0 0 10px var(--cyan), 0 0 30px var(--blue); }

        .aside { margin-top: -1.2rem; font-size: .8rem; letter-spacing: .12em; color: #8d82b3; }
        .sign + .aside, .logo + .aside { margin-top: -.6rem; }
        .tape { width: min(100%, 440px); aspect-ratio: 1.6; padding: 5%; border-radius: 14px; position: relative;
            background: linear-gradient(145deg, #2b2440, #16112a); border: 2px solid #3d3560; box-shadow: 0 16px 40px rgba(0, 0, 0, .6), 0 0 30px rgba(255, 60, 172, .25); }
        .tape .label { height: 72%; border-radius: 6px; padding: 4% 5% 0; display: grid; grid-template-rows: auto 1fr; text-align: left;
            background: linear-gradient(#f4ecd8 0 30%, var(--sun) 30% 40%, var(--orange) 40% 50%, var(--pink) 50% 60%, #f4ecd8 60%); color: #1b1030; }
        .tape .label b { font-family: 'Kaushan Script', cursive; font-weight: normal; font-size: clamp(.9rem, 3.6vw, 1.3rem); line-height: 1.1; white-space: nowrap; }
        .tape .label span { font-size: .7rem; letter-spacing: .15em; }
        .tape .label a { color: #c4190f; text-decoration: none; }
        .tape .label a:hover { text-decoration: underline; }
        .tape .window { position: absolute; left: 25%; right: 25%; top: 45%; height: 22%; border-radius: 40px; background: #0d0a1c; border: 2px solid #3d3560;
            display: flex; justify-content: space-between; align-items: center; padding: 0 6%; }
        .reel { height: 78%; aspect-ratio: 1; border-radius: 50%; border: 4px dotted #eae6ff; animation: spin 3s linear infinite; }
        .tape:hover .reel { animation-duration: .6s; }
        @keyframes spin { to { rotate: 360deg; } }
        .tape .side { position: absolute; left: 7%; top: 8%; font-family: 'Share Tech Mono', monospace; font-size: .75rem; background: #1b1030; color: #f4ecd8; padding: 0 .4rem; border-radius: 3px; }
        .tape::after { content: ''; position: absolute; left: 18%; right: 18%; bottom: 0; height: 18%; background: #221b38; border: 2px solid #3d3560; border-bottom: 0; clip-path: polygon(8% 0, 92% 0, 100% 100%, 0 100%); }
        .tape .screws { z-index: 1; position: absolute; inset: auto 10% 6%; display: flex; justify-content: space-between; }
        .tape .screws i { width: 10px; height: 10px; border-radius: 50%; background: #3d3560; }

        .tracks { width: min(100%, 520px); list-style: none; padding: 0; text-align: left; border-top: 1px solid rgba(62, 242, 255, .3); }
        .tracks a { display: grid; grid-template-columns: 2.2rem 1fr auto; gap: 0 .6rem; padding: .6rem .3rem; text-decoration: none; border-bottom: 1px solid rgba(62, 242, 255, .3); }
        .tracks a:hover { background: rgba(255, 60, 172, .12); }
        .tracks a:focus-visible { outline-offset: 2px; }
        .tracks .no { color: var(--pink); } .tracks .name { color: var(--cyan); overflow-wrap: anywhere; } .tracks .len { color: var(--sun); font-variant-numeric: tabular-nums; }
        .tracks .dl { grid-column: 2 / -1; color: #8d82b3; font-size: .75rem; font-variant-numeric: tabular-nums; }
        .tracks .dl b { font-weight: normal; font-size: 1.05rem; color: #58e78e; text-shadow: 0 0 8px #58e78e; }
        .tracks small { text-wrap: pretty; grid-column: 2 / -1; color: #b3a9d6; font-size: .8rem; }
        .total { display: grid; justify-items: center; gap: 1.1rem; color: #b3a9d6; font-size: .9rem; letter-spacing: .08em; }
        .total b { font-family: 'Monoton', cursive; font-size: clamp(2.4rem, 9vw, 3.6rem); line-height: 1; letter-spacing: .04em; font-variant-numeric: tabular-nums; color: #58e78e; font-weight: normal; text-shadow: 0 0 8px #58e78e, 0 0 24px rgba(88, 231, 142, .6); }
        .play { display: inline-flex; gap: .6rem; align-items: center; padding: .5rem 1.3rem; border-radius: 999px; text-decoration: none; color: #fff; border: 2px solid var(--pink);
            box-shadow: 0 0 14px var(--pink), inset 0 0 14px rgba(255, 60, 172, .5); transition: background .2s, color .2s, translate .1s; }
        .play:hover { background: var(--pink); color: var(--bg); }
        .play:active { translate: 0 1px; }

        .sign { display: block; width: min(100%, 270px); padding: 1rem 1.35rem; border-radius: 12px; border: 3px solid #58e78e;
            box-shadow: 0 0 10px #58e78e, 0 0 36px rgba(88, 231, 142, .45), inset 0 0 18px rgba(88, 231, 142, .35); transition: box-shadow .2s; }
        .sign:hover { box-shadow: 0 0 16px #58e78e, 0 0 60px rgba(88, 231, 142, .7), inset 0 0 24px rgba(88, 231, 142, .5); }
        .sign svg { display: block; width: 100%; height: auto; }
        .logo { --glow: 255, 201, 60; display: block; width: min(100%, 260px); filter: drop-shadow(0 0 18px rgba(var(--glow), .35)); transition: filter .2s; }
        .logo:hover { filter: drop-shadow(0 0 28px rgba(var(--glow), .6)); }
        .logo img { display: block; width: 100%; height: auto; }
        .nos { --glow: 249, 115, 22; }
        .sign .st0 { fill: #58e78e; } .sign .st1 { fill: #48aa7b; } .sign .st2 { fill: #f4f2ff; } .sign .st3 { fill: #284898; }

        .cat { font: 1.4rem/1.2 'Share Tech Mono', monospace; text-align: left; color: var(--sun); text-shadow: 0 0 10px var(--orange); }
        .cat-eye { display: inline-block; }
        @keyframes cat-blink { 0%, 42%, 58%, 100% { scale: 1 1; } 48%, 52% { scale: 1 .12; } }
        @supports (animation-timeline: view()) {
            .cat-eye { animation: cat-blink linear both; animation-timeline: view(); animation-range: entry 0% entry 100%; }
        }
        .outro { min-height: 430px; align-content: start; padding-top: 4rem; padding-bottom: 200px; isolation: isolate;
            background: radial-gradient(ellipse 55% 14% at 50% 85%, rgba(62, 242, 255, .13), transparent), radial-gradient(ellipse at 50% 85%, rgba(43, 134, 255, .22), transparent 65%); }
        .outro::after { content: ''; position: absolute; inset: auto 0 4px; height: 58px; z-index: -1; pointer-events: none;
            background: radial-gradient(ellipse 2% 95% at 9% 0, rgba(62, 242, 255, .26), transparent), radial-gradient(ellipse 3% 100% at 25.5% 0, rgba(43, 134, 255, .32), transparent), radial-gradient(ellipse 2% 70% at 62.5% 0, rgba(62, 242, 255, .18), transparent), radial-gradient(ellipse 3% 100% at 71.5% 0, rgba(62, 242, 255, .28), transparent), radial-gradient(ellipse 2% 90% at 89% 0, rgba(43, 134, 255, .3), transparent);
            filter: blur(6px); mask-image: linear-gradient(#000, transparent); }
        .outro-skyline { position: absolute; bottom: 62px; left: 0; width: 100%; height: 130px; z-index: -1; pointer-events: none;
            fill: rgba(7, 0, 26, .8); stroke: rgba(62, 242, 255, .3); stroke-width: 1; mask-image: linear-gradient(90deg, transparent, #000 20%, #000 80%, transparent); }
        .cya { font-family: 'Monoton', cursive; font-size: clamp(2.4rem, 10vw, 4rem); color: #fff; text-shadow: 0 0 8px var(--cyan), 0 0 24px var(--cyan), 0 0 48px var(--blue); }

        footer { font-size: .85rem; color: #b3a9d6; }
        footer h2 { font-weight: normal; font-size: .75rem; letter-spacing: .3em; text-transform: uppercase; color: var(--pink); margin-bottom: .4rem; }
        footer address { font-style: normal; }
        footer a { display: inline-block; padding-block: .2rem; color: var(--cyan); text-decoration: none; }
        footer a:hover { text-decoration: underline; }

        @media (max-width: 600px) {
            main::before { left: -65%; width: 160%; height: 700px; opacity: .7; }
            .outro::after { left: -40%; right: -40%; }
            .outro { min-height: 360px; padding-bottom: 160px; }
            .outro-skyline { width: 180%; left: -40%; height: 100px; }
        }
        @media (prefers-reduced-motion: reduce) { *, *::before, *::after { animation: none !important; transition: none !important; } }
    </style>
</head>
